/**
 * @file seed-recipes.ts
 * @description Preinstalled example recipes of the cookbook.
 *
 * These recipes ship with the app so the library is never empty: they show up in every
 * category page and in the "All recipes" view next to the recipes generated by the user.
 * They live only in this file and are merged into the Firebase results at read time, which means
 * they are never written to the database and therefore can never be duplicated by repeated loads.
 * Their ids use the stable `seed-` prefix so the library service can resolve them
 * without a network request (see RecipeLibraryService.getRecipeById).
 */
import type { CookbookRecipeRecord } from '../recipe-library.service';

