/**
 * Checks whether a recipe id belongs to a preinstalled recipe.
 * @param recipeId - Id from a route or a Firebase record.
 * @returns True when the id uses the seed prefix.
 */
export function isSeedRecipeId(recipeId: string): boolean {
  return recipeId.startsWith(SEED_RECIPE_ID_PREFIX);
}

/**
 * Looks up a preinstalled recipe by its id.
 * @param recipeId - Id from the recipe detail route.
 * @returns The preinstalled recipe, or null when the id is unknown.
 */
export function findSeedRecipe(recipeId: string): CookbookRecipeRecord | null {
  return seedRecipes.find((recipe) => recipe.id === recipeId) ?? null;
}

/**
 * Adds the preinstalled recipes to the recipes loaded from Firebase.
 * A stored recipe with the same id always wins, so nothing is listed twice.
 * @param storedRecipes - Recipes read from Firebase (may be empty when the database is unreachable).
 * @returns The stored recipes plus every preinstalled recipe that is not already contained.
 */
export function mergeWithSeedRecipes(storedRecipes: CookbookRecipeRecord[]): CookbookRecipeRecord[] {
  const storedIds = new Set(storedRecipes.map((recipe) => recipe.id));
  return [...storedRecipes, ...seedRecipes.filter((recipe) => !storedIds.has(recipe.id))];
}
